"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createCalendarItem(data: {
  titel: string;
  documentType: string;
  datum: string;
  startTime: string;
  endTime: string;
}) {
  try {
    const user = await prisma.user.findFirst();
    if (!user) return { success: false, error: "Gebruiker niet gevonden." };

    // Tarih ve Saatleri ISO formatında birleştiriyoruz
    // Örnek: "2024-10-25" + "T" + "14:30" + ":00"
    const start = new Date(`${data.datum}T${data.startTime}:00`);
    const end = new Date(`${data.datum}T${data.endTime}:00`);

    // Veritabanı tablo ismin "calender" (şemana göre kontrol et)
    await prisma.calender.create({
      data: {
        userId: user.id,
        title: data.titel,
        description: data.documentType, // agenda, assignment vb.
        startDatetime: start,
        endDatetime: end,
      },
    });

    revalidatePath("/calendar");
    return { success: true };
  } catch (error: any) {
    console.error("Calendar Save Error:", error);
    return { success: false, error: error.message };
  }
}

export async function deleteCalendarItem(id: string) {
  try {
    await prisma.calender.delete({
      where: { id },
    });
    revalidatePath("/calendar");
    return { success: true };
  } catch (error) {
    return { success: false, error: "Verwijderen mislukt" };
  }
}